insert into questions (level, category, question_text, options, correct_option_index, explanation, skill_key, skill_step) values
  (1, 'spatial', 'It is 7 o''clock. Which number does the hour hand point at?', '["7", "12", "1", "6"]', 0, 'At 7 o''clock the short hour hand points at the 7 and the long minute hand points at the 12.', 'clocks_angles', 1),
  (1, 'spatial', 'At 5 o''clock, where do the two hands of a clock point?', '["Hour hand at 12, minute hand at 5", "Hour hand at 5, minute hand at 12", "Hour hand at 5, minute hand at 6", "Both hands at 5"]', 1, 'At any o''clock time the minute hand points at the 12. The hour hand points at the hour, here the 5.', 'clocks_angles', 2),
  (1, 'spatial', 'The long hand points at the 6. The short hand is halfway between the 7 and the 8. What time is it?', '["6 past 7", "7 o''clock", "Half past 7", "Half past 8"]', 2, 'The long minute hand at the 6 means 30 minutes, or half past. The short hand has gone past the 7 but not reached the 8, so it is half past 7.', 'clocks_angles', 2),
  (1, 'spatial', 'How many minutes are there in one hour?', '["12", "100", "30", "60"]', 3, 'One hour is 60 minutes. The minute hand goes all the way round the clock once.', 'clocks_angles', 1),
  (1, 'spatial', 'Dev reads a book from 7:00 to 7:30. How long does he read?', '["Half an hour", "3 hours", "A quarter of an hour", "One hour"]', 0, 'From 7:00 to 7:30 is 30 minutes, which is half an hour.', 'clocks_angles', 1),
  (1, 'spatial', 'How many minutes are there in a quarter of an hour?', '["4", "15", "30", "25"]', 1, 'A quarter is one of 4 equal parts. 60 minutes split into 4 parts is 15 minutes each.', 'clocks_angles', 2),
  (1, 'spatial', 'School starts at 8 o''clock and lunch is at 12 o''clock. How many hours is that?', '["20", "3", "4", "5"]', 2, 'Count on from 8: 9, 10, 11, 12. That is 4 hours.', 'clocks_angles', 2),
  (1, 'spatial', 'A film starts at 3 o''clock and lasts 2 hours. What time does it end?', '["6 o''clock", "1 o''clock", "4 o''clock", "5 o''clock"]', 3, 'Count on 2 hours from 3 o''clock: 4 o''clock, 5 o''clock.', 'clocks_angles', 1),
  (1, 'spatial', 'Riya goes to sleep at 9 o''clock at night and wakes up at 6 o''clock in the morning. How many hours does she sleep?', '["9", "15", "3", "8"]', 0, 'From 9 at night to 12 midnight is 3 hours. From 12 midnight to 6 in the morning is 6 more hours. 3 + 6 = 9 hours.', 'clocks_angles', 3),
  (1, 'spatial', 'It is 2 o''clock. Which number will the minute hand point at 15 minutes later?', '["1", "3", "6", "2"]', 1, 'At 2 o''clock the minute hand is at the 12. Each number is 5 minutes, so 15 minutes later it has moved 3 numbers, to the 3.', 'clocks_angles', 2),
  (1, 'spatial', 'It is 4 o''clock now. What time will it be in 1 hour and 30 minutes?', '["5 o''clock", "Half past 4", "Half past 5", "Half past 6"]', 2, '1 hour after 4 o''clock is 5 o''clock. 30 more minutes makes it half past 5.', 'clocks_angles', 3),
  (1, 'spatial', 'The time is 6:15. Which number does the minute hand point at?', '["15", "1", "6", "3"]', 3, '15 minutes past means the minute hand has moved 3 numbers from the 12 (5, 10, 15), so it points at the 3.', 'clocks_angles', 2),
  (1, 'spatial', 'A clock shows 8 o''clock. What time was it one hour ago?', '["7 o''clock", "6 o''clock", "8 o''clock", "9 o''clock"]', 0, 'One hour before 8 o''clock is 7 o''clock.', 'clocks_angles', 1),
  (1, 'spatial', 'Which of these times comes first in the morning?', '["8:00", "6:45", "7:15", "7:30"]', 1, '6:45 is before 7 o''clock, and the others are all at 7 o''clock or later.', 'clocks_angles', 2),
  (1, 'spatial', 'A clock shows 3 o''clock. What kind of corner do the two hands make?', '["No corner - the hands are on top of each other", "A very thin, narrow corner", "A square corner (a right angle)", "A straight line"]', 2, 'At 3 o''clock one hand points up at the 12 and the other points right at the 3. That makes a square corner, like the corner of a book.', 'clocks_angles', 2),
  (1, 'spatial', 'At 6 o''clock, what do the two hands of a clock make?', '["A square corner", "A very small corner", "Both hands point the same way", "A straight line"]', 3, 'At 6 o''clock the minute hand points up at the 12 and the hour hand points down at the 6, so together they make one straight line.', 'clocks_angles', 2),
  (1, 'spatial', 'At 9 o''clock the minute hand points at the 12. Where does the hour hand point?', '["At the 9", "At the 12", "At the 6", "At the 3"]', 0, 'At 9 o''clock the short hour hand points at the 9.', 'clocks_angles', 1),
  (1, 'spatial', 'How many hours does it take the hour hand to go all the way around the clock once?', '["1", "12", "60", "24"]', 1, 'The hour hand moves from one number to the next each hour. There are 12 numbers, so a full turn takes 12 hours.', 'clocks_angles', 3),
  (1, 'spatial', 'Ali starts his homework at 5:00 and finishes at 5:20. How many minutes did it take?', '["25", "15", "20", "5"]', 2, 'From 5:00 to 5:20 is 20 minutes.', 'clocks_angles', 1),
  (1, 'spatial', 'A cake must bake for 30 minutes. It goes into the oven at 4:15. When is it ready?', '["4:30", "4:35", "5:15", "4:45"]', 3, 'Add 30 minutes to 4:15: 15 + 30 = 45, so it is ready at 4:45.', 'clocks_angles', 3),
  (1, 'spatial', 'The bus comes at 8:30. Meera gets to the bus stop at 8:20. How long does she wait?', '["10 minutes", "20 minutes", "50 minutes", "30 minutes"]', 0, 'From 8:20 to 8:30 is 10 minutes.', 'clocks_angles', 2),
  (1, 'spatial', 'Which time is the same as half past 2?', '["3:30", "2:30", "2:50", "2:15"]', 1, 'Half past means 30 minutes past the hour, so half past 2 is 2:30.', 'clocks_angles', 1),
  (1, 'spatial', 'Which time is the same as quarter past 9?', '["9:25", "8:45", "9:15", "9:45"]', 2, 'Quarter past means 15 minutes past the hour, so quarter past 9 is 9:15.', 'clocks_angles', 2),
  (1, 'spatial', 'It is quarter to 4. How is this time written in numbers?', '["3:15", "4:15", "4:45", "3:45"]', 3, 'Quarter to 4 means 15 minutes before 4 o''clock. 15 minutes before 4:00 is 3:45.', 'clocks_angles', 3),
  (1, 'spatial', 'The minute hand moves from the 12 to the 6. How many minutes have passed?', '["30", "60", "15", "6"]', 0, 'The 12 to the 6 is half way round the clock, and half of 60 minutes is 30 minutes.', 'clocks_angles', 1),
  (1, 'spatial', 'A pencil is 15 cm long. A crayon is 8 cm long. How much longer is the pencil?', '["5 cm", "7 cm", "8 cm", "23 cm"]', 1, '15 - 8 = 7, so the pencil is 7 cm longer.', 'measuring', 1),
  (1, 'spatial', 'How many centimetres are there in 1 metre?', '["10", "1000", "100", "50"]', 2, '1 metre is the same as 100 centimetres.', 'measuring', 1),
  (1, 'spatial', 'Which unit would you use to measure the length of a classroom?', '["Minutes", "Litres", "Kilograms", "Metres"]', 3, 'Length is measured in metres (or centimetres). Litres are for liquids, kilograms for weight and minutes for time.', 'measuring', 1),
  (1, 'spatial', 'Which unit would you use to measure how heavy a bag of rice is?', '["Kilograms", "Metres", "Centimetres", "Litres"]', 0, 'How heavy something is (its weight) is measured in kilograms or grams.', 'measuring', 1),
  (1, 'spatial', 'Which of these would you measure in litres?', '["The time of a race", "The water in a bucket", "The length of a pencil", "The weight of a bag"]', 1, 'Litres measure how much liquid something holds, like water in a bucket.', 'measuring', 1),
  (1, 'spatial', 'One end of a crayon is at the 0 mark of a ruler and the other end is at the 9 cm mark. How long is the crayon?', '["10 cm", "8 cm", "9 cm", "0 cm"]', 2, 'The crayon starts at 0 and ends at 9, so it is 9 cm long.', 'measuring', 1),
  (1, 'spatial', 'A pencil lies along a ruler from the 3 cm mark to the 10 cm mark. How long is the pencil?', '["13 cm", "10 cm", "3 cm", "7 cm"]', 3, 'The pencil does not start at 0. Its length is the end minus the start: 10 - 3 = 7 cm.', 'measuring', 3),
  (1, 'spatial', 'A ribbon is 20 cm long. You cut off 6 cm. How long is the rest of the ribbon?', '["14 cm", "26 cm", "16 cm", "12 cm"]', 0, '20 - 6 = 14, so 14 cm of ribbon is left.', 'measuring', 1),
  (1, 'spatial', 'A square has sides 3 cm long. How far is it all the way around the square?', '["6 cm", "12 cm", "3 cm", "9 cm"]', 1, 'A square has 4 equal sides. 3 + 3 + 3 + 3 = 12 cm.', 'measuring', 2),
  (1, 'spatial', 'A rectangle is 5 cm long and 2 cm wide. How far is it all the way around the rectangle?', '["10 cm", "7 cm", "14 cm", "12 cm"]', 2, 'Go round all 4 sides: 5 + 2 + 5 + 2 = 14 cm.', 'measuring', 3),
  (1, 'spatial', 'Which is heavier: 1 kilogram of rice or 500 grams of sugar?', '["The sugar", "It cannot be told", "They weigh the same", "The rice"]', 3, '1 kilogram is 1000 grams, which is more than 500 grams, so the rice is heavier.', 'measuring', 2),
  (1, 'spatial', 'How many grams are there in 1 kilogram?', '["1000", "10", "500", "100"]', 0, '1 kilogram is the same as 1000 grams.', 'measuring', 2),
  (1, 'spatial', 'A jug holds 3 litres of juice. Each glass holds half a litre. How many glasses can the jug fill?', '["9", "6", "5", "3"]', 1, 'Each litre fills 2 half-litre glasses. 3 litres fill 3 x 2 = 6 glasses.', 'measuring', 3),
  (1, 'spatial', 'Which is the best guess for the height of a door?', '["200 kilometres", "20 metres", "2 metres", "2 centimetres"]', 2, 'A door is a bit taller than a grown-up, about 2 metres. 2 cm is tiny and 20 m is as tall as a building.', 'measuring', 2),
  (1, 'spatial', 'Which is the best guess for the length of a spoon?', '["1 centimetre", "150 centimetres", "15 metres", "15 centimetres"]', 3, 'A spoon fits in your hand, about 15 cm. 15 m is longer than a bus.', 'measuring', 2),
  (1, 'spatial', 'Which is the best guess for the weight of one apple?', '["150 grams", "150 kilograms", "15 kilograms", "1 gram"]', 0, 'An apple is light, about 150 grams. 15 kilograms is as heavy as a big bag of rice.', 'measuring', 2),
  (1, 'spatial', 'A plant was 12 cm tall. A week later it is 17 cm tall. How much did it grow?', '["29 cm", "5 cm", "12 cm", "7 cm"]', 1, '17 - 12 = 5, so it grew 5 cm.', 'measuring', 1),
  (1, 'spatial', 'Rohan is 120 cm tall. His sister is 15 cm shorter than him. How tall is she?', '["135 cm", "100 cm", "105 cm", "115 cm"]', 2, 'Shorter means take away: 120 - 15 = 105 cm.', 'measuring', 2),
  (1, 'spatial', 'A path is 3 metres long. How many centimetres is that?', '["103", "3000", "30", "300"]', 3, 'Each metre is 100 cm, so 3 metres is 3 x 100 = 300 cm.', 'measuring', 3),
  (1, 'spatial', 'Ana''s string is 1 metre long. Ben''s string is 80 cm long. Whose string is longer, and by how much?', '["Ana''s, by 20 cm", "They are the same length", "Ben''s, by 20 cm", "Ana''s, by 79 cm"]', 0, '1 metre is 100 cm. 100 - 80 = 20, so Ana''s string is 20 cm longer.', 'measuring', 3),
  (1, 'spatial', 'One box weighs 4 kg. How much do 3 of these boxes weigh?', '["15 kg", "12 kg", "7 kg", "10 kg"]', 1, '3 boxes of 4 kg: 4 + 4 + 4 = 12 kg.', 'measuring', 1),
  (1, 'spatial', 'Which holds more: a 1 litre bottle or a 500 millilitre bottle?', '["It cannot be told", "The 500 millilitre bottle", "The 1 litre bottle", "They hold the same"]', 2, '1 litre is 1000 millilitres, which is more than 500 millilitres.', 'measuring', 2),
  (1, 'spatial', 'Each tile is 10 cm long. How many tiles laid end to end make 1 metre?', '["5", "1", "100", "10"]', 3, '1 metre is 100 cm. 100 cm split into 10 cm tiles is 10 tiles.', 'measuring', 3),
  (1, 'spatial', 'Sara measures a book with paper clips. It is 6 clips long, and each clip is 3 cm long. How long is the book?', '["18 cm", "9 cm", "6 cm", "3 cm"]', 0, '6 clips of 3 cm each: 6 x 3 = 18 cm.', 'measuring', 2),
  (1, 'spatial', 'Line A is 7 cm long, line B is 11 cm and line C is 9 cm. Which order goes from shortest to longest?', '["C, A, B", "A, C, B", "B, C, A", "A, B, C"]', 1, '7 cm is the shortest, then 9 cm, then 11 cm: A, C, B.', 'measuring', 2),
  (1, 'spatial', 'A square piece of paper is folded in half from one corner to the opposite corner. What shape is the folded paper?', '["A smaller square", "A circle", "A triangle", "A rectangle"]', 2, 'Folding a square corner to corner lays one half exactly on the other along the diagonal, which makes a triangle.', 'folding', 1),
  (1, 'spatial', 'A square piece of paper is folded in half so the top edge meets the bottom edge. What shape is the folded paper?', '["A smaller square", "A circle", "A triangle", "A rectangle"]', 3, 'Folding edge to edge halves the height but keeps the width, so the square becomes a long rectangle.', 'folding', 1),
  (1, 'spatial', 'You fold a sheet of paper in half, and then in half again. When you open it out, how many equal parts do the creases make?', '["4", "3", "8", "2"]', 0, 'Each fold doubles the number of parts: 1 fold makes 2 parts, 2 folds make 4 parts.', 'folding', 2),
  (1, 'spatial', 'A paper is folded in half and then in half again, so it is 4 layers thick. One hole is punched through all the layers. How many holes are there when you open it?', '["8", "4", "1", "2"]', 1, 'The punch goes through every layer, and there are 4 layers, so there are 4 holes.', 'folding', 2),
  (1, 'spatial', 'A paper is folded in half 3 times, so it is 8 layers thick. One hole is punched through all the layers. How many holes are there when you open it?', '["4", "6", "8", "3"]', 2, 'Every fold doubles the layers: 2, 4, 8. One punch through 8 layers makes 8 holes.', 'folding', 3),
  (1, 'spatial', 'Which of these can be folded down the middle so both halves match exactly?', '["The letter R", "The number 2", "The letter L", "A butterfly shape"]', 3, 'A butterfly has matching wings on each side of its body. R, L and 2 look different on each side.', 'folding', 1),
  (1, 'spatial', 'In how many different ways can you fold a square in half so the two halves match exactly?', '["4", "1", "8", "2"]', 0, 'Top to bottom, side to side, and along each of the 2 corner-to-corner lines: 4 ways.', 'folding', 3),
  (1, 'spatial', 'A rectangle is longer than it is wide (it is not a square). In how many ways can you fold it in half so the two halves match exactly?', '["0", "2", "1", "4"]', 1, 'Top to bottom or side to side. Folding corner to corner does not work for a rectangle that is not a square.', 'folding', 3),
  (1, 'spatial', 'A square paper is folded corner to corner to make a triangle, then folded corner to corner the other way to make a smaller triangle. When you open it, how many triangles do the creases make?', '["3", "2", "4", "8"]', 2, 'The two creases cross in the middle of the square and split it into 4 triangles.', 'folding', 3),
  (1, 'spatial', 'A paper is folded in half. A small triangle is cut out with one of its sides along the crease. When you open the paper, what does the hole look like?', '["Two separate triangles", "A circle", "A triangle", "A diamond shape"]', 3, 'The cut triangle is doubled on both sides of the crease, so the two halves join into one diamond shape.', 'folding', 3),
  (1, 'spatial', 'A letter is folded into 3 equal parts so it fits into an envelope. When you open it, how many creases do you see?', '["2", "3", "1", "4"]', 0, 'Splitting the paper into 3 parts needs only 2 fold lines between them.', 'folding', 2),
  (1, 'spatial', 'A long strip of paper is folded in half, and then in half again in the same direction. When you open it, how many creases do you see?', '["1", "3", "4", "2"]', 1, 'The strip is now in 4 equal parts, and there is one crease between each pair of parts: 3 creases.', 'folding', 3),
  (1, 'spatial', 'A square napkin is 20 cm wide. It is folded in half to make a rectangle. How long are the sides of the rectangle?', '["10 cm and 10 cm", "40 cm and 10 cm", "20 cm and 10 cm", "20 cm and 20 cm"]', 2, 'One side stays 20 cm. The other side is halved: 20 / 2 = 10 cm.', 'folding', 3),
  (1, 'spatial', 'A sheet of paper is folded in half. How thick is the folded paper compared with one sheet?', '["Half as thick", "The same", "4 times as thick", "Twice as thick"]', 3, 'Folding in half puts 2 layers on top of each other, so it is twice as thick.', 'folding', 1),
  (1, 'spatial', 'You put a blob of wet paint on one half of a paper, fold it in half, press it and open it. Where is the paint now?', '["On both halves, matching each other", "All over the paper", "Only on the first half", "Only on the crease"]', 0, 'Pressing the halves together prints the blob on the other half too, like a mirror. That is how butterfly paintings are made.', 'folding', 1),
  (1, 'spatial', 'There is a wet paint dot near the top left corner of a paper. You fold the left half over onto the right half and press. Where does the matching dot appear?', '["Near the bottom left corner", "Near the top right corner", "Near the bottom right corner", "In the middle"]', 1, 'Folding left onto right flips the dot across the middle line. It stays at the top but moves to the right side.', 'folding', 2),
  (1, 'spatial', 'There is a wet paint dot near the top left corner of a paper. You fold the top half down onto the bottom half and press. Where does the matching dot appear?', '["Near the bottom right corner", "Near the top right corner", "Near the bottom left corner", "In the middle"]', 2, 'Folding top onto bottom flips the dot across the middle line from top to bottom. It stays on the left side.', 'folding', 3),
  (1, 'spatial', 'Which of these can NOT be folded in half so both halves match exactly?', '["A circle", "A square", "A heart", "The letter F"]', 3, 'A circle, a square and a heart all have a line where the halves match. The letter F does not.', 'folding', 2),
  (1, 'spatial', 'A paper circle is folded in half, and then in half again. What shape is it now?', '["A quarter circle, like a pizza slice", "A square", "A half circle", "A full circle"]', 0, 'The first fold makes a half circle. Folding that in half makes a quarter circle with a pointed corner.', 'folding', 2),
  (1, 'spatial', 'A square paper is folded in half to make a rectangle. The rectangle is then folded in half the other way. What shape is it now?', '["A triangle", "A smaller square", "A circle", "A thinner rectangle"]', 1, 'The first fold halves one side, the second fold halves the other side. Both sides are now half as long, so it is a small square.', 'folding', 3),
  (1, 'spatial', 'How many times must you fold a paper in half to make it 4 layers thick?', '["3", "1", "2", "4"]', 2, '1 fold makes 2 layers, and 2 folds make 4 layers.', 'folding', 2),
  (1, 'spatial', 'A long paper strip is folded in half. Then you make one straight cut across the folded strip (not along the fold). How many pieces do you get?', '["4", "1", "2", "3"]', 3, 'The cut goes through both layers. You get the folded part with the crease in one piece, plus the two loose ends: 3 pieces.', 'folding', 3),
  (1, 'spatial', 'A square paper is folded corner to corner and then opened. Where is the crease?', '["From one corner to the opposite corner", "From the middle of the top edge to the middle of the bottom edge", "All around the edges", "There is no crease"]', 0, 'The fold was made corner to corner, so that is where the crease line goes.', 'folding', 1),
  (1, 'spatial', 'A square paper has a dot exactly in its centre. You fold it in half, edge to edge. Where is the dot now?', '["At a corner", "On the crease", "On an outside edge", "It has disappeared"]', 1, 'A fold that halves the square passes right through its centre, so the dot sits on the crease.', 'folding', 2),
  (1, 'spatial', 'A rectangle of paper is 10 cm long and 6 cm wide. It is folded in half so the two short sides meet. What size is the folded paper?', '["10 cm by 3 cm", "20 cm by 6 cm", "5 cm by 6 cm", "5 cm by 3 cm"]', 2, 'Bringing the short sides together halves the long side: 10 / 2 = 5 cm. The 6 cm side stays the same.', 'folding', 3),
  (1, 'spatial', 'A cardboard box is shaped like a cube, but it has no lid. How many faces does it have?', '["6", "4", "8", "5"]', 3, 'A closed cube has 6 faces. Without the lid on top, there are 5 left: bottom, front, back, left and right.', 'cubes_blocks', 3),
  (1, 'spatial', 'Kabir builds a tower of 3 blocks. He takes the top block off and puts it on the floor next to the tower. How many blocks touch the floor now?', '["2", "3", "1", "0"]', 0, 'The tower''s bottom block touches the floor, and so does the block he put down beside it: 2 blocks.', 'cubes_blocks', 2),
  (1, 'spatial', 'You have 5 blocks. How many more blocks do you need to build a tower 12 blocks tall?', '["17", "7", "5", "6"]', 1, '12 - 5 = 7 more blocks.', 'cubes_blocks', 1),
  (1, 'spatial', 'A floor is covered with 2 rows of 5 blocks. Then one more block is put on top of every block. How many blocks are there now?', '["10", "12", "20", "15"]', 2, 'The floor has 2 x 5 = 10 blocks. Another 10 go on top: 10 + 10 = 20 blocks.', 'cubes_blocks', 2),
  (1, 'spatial', 'A tower is 6 blocks tall. You put 3 more blocks on top. How many blocks tall is it now?', '["3", "6", "18", "9"]', 3, '6 + 3 = 9 blocks.', 'cubes_blocks', 1),
  (1, 'spatial', 'A row of 4 blocks sits on the floor. A second row of 4 blocks is put on top of it. How many blocks are there?', '["8", "16", "4", "6"]', 0, '2 rows of 4 blocks: 4 + 4 = 8 blocks.', 'cubes_blocks', 1),
  (1, 'spatial', 'A floor is covered with 4 rows of blocks, and each row has 4 blocks. How many blocks are there?', '["20", "16", "8", "12"]', 1, '4 rows of 4: 4 + 4 + 4 + 4 = 16 blocks.', 'cubes_blocks', 2),
  (1, 'spatial', 'A tower has a red block at the bottom, a blue block in the middle and a green block on top. You turn the whole tower upside down. Which colour is on top now?', '["All of them", "Blue", "Red", "Green"]', 2, 'Turning it upside down swaps the top and the bottom, so the red bottom block is now on top. Blue stays in the middle.', 'cubes_blocks', 2),
  (1, 'spatial', 'A cube sits on a table. You look at it from straight above. What shape do you see?', '["Three faces of the cube", "A triangle", "A circle", "A square"]', 3, 'From straight above you only see the top face, and every face of a cube is a square.', 'cubes_blocks', 2),
  (1, 'spatial', 'Three cubes are stacked into a tower. How many cube faces are pressed against another cube?', '["4", "2", "3", "6"]', 0, 'There are 2 places where cubes meet, and at each place 2 faces touch each other: 2 x 2 = 4 faces.', 'cubes_blocks', 3),
  (1, 'spatial', 'Two cubes are glued side by side to make one long brick shape. How many flat faces does the brick have?', '["10", "6", "8", "12"]', 1, 'The brick has a top, a bottom, a front, a back and two ends: 6 faces. The faces glued together are hidden inside.', 'cubes_blocks', 3),
  (1, 'spatial', 'A tower has 10 blocks. Every second block is red, starting with the bottom block. How many blocks are red?', '["4", "10", "5", "6"]', 2, 'Red blocks are the 1st, 3rd, 5th, 7th and 9th from the bottom: 5 red blocks.', 'cubes_blocks', 2),
  (1, 'spatial', 'Meera has 20 blocks. She builds towers that are 5 blocks tall each. How many towers can she build?', '["15", "25", "5", "4"]', 3, '5 + 5 + 5 + 5 = 20, so she can build 4 towers.', 'cubes_blocks', 1),
  (1, 'spatial', 'A box shape is built 3 blocks long, 2 blocks wide and 1 block tall. How many blocks does it use?', '["6", "5", "9", "7"]', 0, 'One layer of 2 rows with 3 blocks in each row: 3 + 3 = 6 blocks.', 'cubes_blocks', 2),
  (1, 'spatial', 'A box shape is built 3 blocks long, 2 blocks wide and 2 blocks tall. How many blocks does it use?', '["10", "12", "7", "6"]', 1, 'Each layer is 2 rows of 3, which is 6 blocks. There are 2 layers: 6 + 6 = 12 blocks.', 'cubes_blocks', 3),
  (1, 'spatial', 'Lena has 9 blocks. She makes a square on the floor with the same number of rows as blocks in each row. How many rows does she make?', '["4", "9", "3", "2"]', 2, '3 rows of 3 blocks is 9 blocks, and 3 rows matches 3 blocks in each row.', 'cubes_blocks', 3),
  (1, 'spatial', 'A tower has 7 blocks, numbered 1 at the bottom up to 7 at the top. Which block is exactly in the middle?', '["Block 3", "Block 5", "Block 7", "Block 4"]', 3, 'Block 4 has 3 blocks below it (1, 2, 3) and 3 blocks above it (5, 6, 7).', 'cubes_blocks', 2),
  (1, 'spatial', 'You look at a tower of 4 cubes from the front. What do you see?', '["4 squares, one on top of another", "4 squares side by side in a row", "1 square", "A triangle"]', 0, 'From the front you see one square face of each cube, stacked up in a column.', 'cubes_blocks', 2),
  (1, 'spatial', 'A tower of 4 cubes stands next to a tower of 2 cubes. You look at them from straight above. How many squares can you see?', '["4", "2", "6", "1"]', 1, 'From above you only see the top cube of each tower, so you see 2 squares.', 'cubes_blocks', 3),
  (1, 'spatial', 'Three blocks are in a row on the floor, and one more block sits on top of the end block. How many blocks are there?', '["5", "3", "4", "6"]', 2, '3 blocks on the floor + 1 block on top = 4 blocks.', 'cubes_blocks', 1),
  (1, 'spatial', 'One tower is 8 blocks tall and another is 4 blocks tall. How many blocks must you move from the tall tower to the short one to make them the same height?', '["3", "1", "4", "2"]', 3, 'There are 12 blocks in all, so each tower should be 6 tall. Moving 2 blocks makes 8 - 2 = 6 and 4 + 2 = 6.', 'cubes_blocks', 3),
  (1, 'spatial', 'A cube has a dot on its top face. You roll it over once, forwards, onto the next face. Where is the dot now?', '["On one of its sides", "It has gone", "On the bottom", "Still on top"]', 0, 'Rolling forwards turns the cube a quarter turn, so the top face moves round to face the front, which is one of the sides.', 'cubes_blocks', 3),
  (1, 'spatial', 'How many small blocks are needed to build a big cube that is 3 blocks wide, 3 blocks long and 3 blocks tall?', '["12", "27", "9", "18"]', 1, 'Each layer is 3 rows of 3, which is 9 blocks. There are 3 layers: 9 + 9 + 9 = 27 blocks.', 'cubes_blocks', 3),
  (1, 'spatial', 'A dice is a cube, and its opposite faces always add up to 7. The 1 is on top. Which number is on the bottom?', '["1", "5", "6", "2"]', 2, 'The bottom is opposite the top, so it must make 7 with the 1: 7 - 1 = 6.', 'cubes_blocks', 2),
  (1, 'spatial', 'Which face of a cube is opposite its top face?', '["The front face", "The top face", "The left face", "The bottom face"]', 3, 'The top and the bottom are on opposite sides of the cube.', 'cubes_blocks', 1);
